// tools/modgui-gen.mjs over a descriptor: omx-plugins' committed MOD GUI of omx-delay (test/fixtures/omx-delay/, its
// descriptor, its declared panel and the six files omx-plugins' own generator wrote) is regenerated byte for byte;
// a moved default, a widget the control cannot take and a plugin with no LV2 URI are each refused or seen; a
// read-only control (a readout) is a display, never a control input; with no declared panel the sections are the
// descriptor's groups; the look resolves to look.json.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { emitLook, TOKENS_CSS, LOOK_JSON } from '../tools/look.mjs';
import { generateModgui, NothingToDraw, resolvePanel } from '../tools/modgui-gen.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const FIX = join(ROOT, 'test/fixtures/omx-delay');
const read = (f) => JSON.parse(readFileSync(join(FIX, f), 'utf8'));
const SOURCE = 'plugins/omx-delay/omx-delay.decl.json (its panel block) and tools/look.json';
const gen = (descriptor = read('omx-delay.descriptor.json'), panel = read('omx-delay.panel.json')) =>
  generateModgui(descriptor, { panel, stem: 'omx-delay', source: SOURCE });
const cli = (...args) => spawnSync(process.execPath, [join(ROOT, 'tools/modgui-gen.mjs'), ...args], { encoding: 'utf8' });
const fixtureArgs = ['--descriptor', join(FIX, 'omx-delay.descriptor.json'), '--panel', join(FIX, 'omx-delay.panel.json'), '--out', join(FIX, 'omx-delay.lv2'), '--source', SOURCE];

test('every file omx-plugins wrote for omx-delay is regenerated byte for byte', () => {
  const files = gen();
  assert.deepEqual(files.map(([p]) => p), ['modgui.ttl', 'modgui/icon-omx-delay.html', 'modgui/stylesheet-omx-delay.css', 'modgui/screenshot-omx-delay.png', 'modgui/thumbnail-omx-delay.png', 'modgui/knobs/omx-knob.png']);
  for (const [p, bytes] of files) assert.ok(readFileSync(join(FIX, 'omx-delay.lv2', p)).equals(bytes), p);
  const r = cli('--check', ...fixtureArgs);
  assert.equal(r.status, 0, r.stderr);
  assert.match(r.stdout, /every generated file is fresh/);
});

test('arm: a moved default is refused by --check, on the template and the images that draw it', () => {
  const d = read('omx-delay.descriptor.json');
  d.controls.find((c) => c.symbol === 'fxDelayTime').travel.default = 600;
  const moved = new Map(gen(d));
  const stale = gen().filter(([p, bytes]) => !moved.get(p).equals(bytes)).map(([p]) => p);
  assert.deepEqual(stale, ['modgui/icon-omx-delay.html', 'modgui/screenshot-omx-delay.png', 'modgui/thumbnail-omx-delay.png']);
});

test('the generation is deterministic', () => {
  const a = gen(), b = gen();
  assert.deepEqual(a.map(([p, x]) => [p, x.toString('base64')]), b.map(([p, x]) => [p, x.toString('base64')]));
});

test('with no declared panel the sections are the descriptor groups and the family its meanings', () => {
  const p = resolvePanel(read('omx-delay.descriptor.json'), { stem: 'omx-delay' });
  assert.equal(p.family, 'delay');
  assert.deepEqual(p.sections.map((s) => [s.key, s.label, s.controls.map((c) => c.symbol)]), [['delay', 'Delay', ['fxDelayTime', 'fxDelayFeedback', 'tone', 'mix', 'pingpong']]]);
  assert.deepEqual(p.sections[0].controls.map((c) => c.widget), ['knob', 'knob', 'knob', 'knob', 'switch']);
});

test('a declared widget is drawn when the control can take it, and refused when it cannot', () => {
  const panel = { ...read('omx-delay.panel.json'), widgets: { mix: 'fader' } };
  assert.ok(gen(undefined, panel).some(([p]) => p === 'modgui/knobs/omx-fader.png'));
  assert.throws(() => gen(undefined, { ...panel, widgets: { mix: 'switch' } }), /'mix' cannot be drawn as a switch/);
  assert.throws(() => gen(undefined, { ...panel, widgets: { mix: 'dial' } }), /'mix' names widget 'dial'/);
});

test('a scanned LV2 compressor with no panel generates, its gain-reduction readout a display and no port', () => {
  const d = JSON.parse(readFileSync(join(ROOT, 'test/fixtures/descriptors/scanned-lv2-compressor.json'), 'utf8'));
  const files = new Map(generateModgui(d, { stem: 'compressor', source: 'test/fixtures/descriptors/scanned-lv2-compressor.json' }));
  const html = files.get('modgui/icon-compressor.html').toString();
  const ttl = files.get('modgui.ttl').toString();
  assert.match(html, /<div class="omx-control omx-display"[^>]* data-symbol="gr" data-min="0" data-max="40">/);
  assert.doesNotMatch(html, /data-symbol="gr"[^>]*data-default/, 'a readout has no default');
  assert.doesNotMatch(html, /mod-role="input-control-port" mod-port-symbol="gr"/, 'a readout is no control input');
  assert.doesNotMatch(ttl, /lv2:symbol "gr"/);
  // the other controls are drawn as before: the inputs are still ports, each with its default
  assert.match(html, /data-symbol="makeup" data-min="0" data-max="24" data-default="0"/);
  assert.match(ttl, /lv2:index 0 ;\n {12}lv2:symbol "threshold"/);
});

test('a read-only control in a declared panel is a display, and a widget named for it is refused', () => {
  const d = read('omx-delay.descriptor.json');
  d.controls.find((c) => c.symbol === 'mix').readonly = true;
  const html = new Map(gen(d)).get('modgui/icon-omx-delay.html').toString();
  assert.match(html, /class="omx-control omx-display"[^>]* data-symbol="mix"/);
  assert.doesNotMatch(html, /mod-port-symbol="mix"/);
  assert.throws(() => gen(d, { ...read('omx-delay.panel.json'), widgets: { mix: 'knob' } }), /'mix' is a readout and takes no widget/);
});

test('a control the descriptor lacks and a plugin with no LV2 URI are refused', () => {
  assert.throws(() => gen(undefined, { family: 'delay', sections: [{ key: 'x', label: 'X', controls: ['nope'] }] }), /panel names 'nope'/);
  const clap = read('omx-delay.descriptor.json');
  delete clap.plugin.uri;
  assert.throws(() => gen(clap), /states no LV2 URI/);
});

test('the CLI refuses a call with no descriptor or no bundle', () => {
  assert.equal(cli('--out', '/tmp/x.lv2').status, 2);
  assert.equal(cli('--descriptor', join(FIX, 'omx-delay.descriptor.json')).status, 2);
});

test('look.json is what tokens.css resolves to, and a moved token moves it', () => {
  const css = readFileSync(TOKENS_CSS, 'utf8');
  assert.equal(emitLook(css), readFileSync(LOOK_JSON, 'utf8'));
  const moved = css.replace(/--accent:[^;]+/g, '--accent: #123456');
  assert.notEqual(moved, css, 'the edit landed');
  assert.notEqual(emitLook(moved), emitLook(css));
});

test('the brand is the vendor, else the plugin name, else the stem: a missing vendor refuses nothing', () => {
  const d = read('omx-delay.descriptor.json');
  const panel = read('omx-delay.panel.json');
  const brand = (x) => resolvePanel(x, { panel, stem: 'omx-delay' }).brand;
  assert.ok(d.plugin.vendor && d.plugin.name, 'the fixture states both');
  assert.equal(brand(d), d.plugin.vendor);
  const name = d.plugin.name;
  delete d.plugin.vendor;
  assert.equal(brand(d), name);
  delete d.plugin.name;
  assert.equal(brand(d), 'omx-delay');
  const ttl = new Map(generateModgui(d, { panel, stem: 'omx-delay', source: 's' })).get('modgui.ttl').toString();
  assert.match(ttl, /modgui:brand "omx-delay"/);
});

test('a descriptor whose controls are all hidden has nothing to draw: a typed error, not a fault (a synth with no LV2 ports)', () => {
  const d = JSON.parse(readFileSync(join(ROOT, 'test/fixtures/descriptors/scanned-lv2-hidden-only.json'), 'utf8'));
  assert.ok(d.controls.length > 0 && d.controls.every((c) => c.hidden), 'the fixture has controls, all hidden');
  assert.throws(() => resolvePanel(d, { stem: 'hidden-only' }), (err) => err instanceof NothingToDraw && err.code === 'MODGUI_NOTHING_TO_DRAW');
});

test('a control name holding a line break, a return or a tab writes Turtle with no raw break inside a string', () => {
  const d = read('omx-delay.descriptor.json');
  const name = 'Fb Tone\nLo<>Hi\rmid\tend "q" \\';
  d.controls.find((c) => c.symbol === 'fxDelayTime').name = name;
  const files = new Map(gen(d));
  const ttl = files.get('modgui.ttl').toString('utf8');
  // A Turtle short string ("...") may not hold a raw line feed or carriage return: with every well-formed
  // string taken out, no quote may be left over (a string cut by a line end leaves one).
  assert.doesNotMatch(ttl.replace(/"(?:[^"\\\n\r]|\\.)*"/g, ''), /"/);
  assert.ok(ttl.includes('lv2:name "Fb Tone\\nLo<>Hi\\rmid\\tend \\"q\\" \\\\"'), ttl);
  // The same name in the icon template stays one HTML attribute and one text node.
  assert.ok(files.get('modgui/icon-omx-delay.html').toString('utf8').includes('Fb Tone'));
});

test('a trigger control beside a normal one is left off the face and reported: the normal one is drawn (the ZLFO shape)', () => {
  const d = read('omx-delay.descriptor.json');
  d.controls.push({ id: 'cv_trigger', name: 'Trigger', kind: 'trigger', meaning: 'unknown' });
  const panel = read('omx-delay.panel.json');
  panel.sections[0].controls.push('cv_trigger');
  const r = resolvePanel(d, { panel, stem: 'omx-delay' });
  assert.deepEqual(r.skipped, ['cv_trigger']);
  assert.ok(!r.sections.flatMap((s) => s.controls).some((c) => c.symbol === 'cv_trigger'));
  assert.ok(r.sections[0].controls.length > 0);
  const ttl = new Map(gen(d, panel)).get('modgui.ttl').toString();
  assert.doesNotMatch(ttl, /cv_trigger/);
  // with no declared panel the layout lists it and the generator still draws the rest
  const auto = resolvePanel(d, { stem: 'omx-delay' });
  assert.deepEqual(auto.skipped, ['cv_trigger']);
  assert.ok(auto.sections.flatMap((s) => s.controls).length > 0);
  // the CLI says so on stderr and exits 0
  const dir = mkdtempSync(join(tmpdir(), 'mg47-'));
  writeFileSync(join(dir, 'd.json'), JSON.stringify(d));
  writeFileSync(join(dir, 'p.json'), JSON.stringify(panel));
  const run = cli('--descriptor', join(dir, 'd.json'), '--panel', join(dir, 'p.json'), '--out', join(dir, 'x.lv2'));
  assert.equal(run.status, 0, run.stderr);
  assert.match(run.stderr, /^modgui: skipped trigger control 'cv_trigger'\n$/);
});

test('a descriptor whose only control is a trigger has nothing to draw: exit 3', () => {
  const d = read('omx-delay.descriptor.json');
  d.controls = [{ id: 'cv_trigger', name: 'Trigger', kind: 'trigger', meaning: 'unknown' }];
  assert.throws(() => resolvePanel(d, { stem: 'omx-delay' }), (err) => err instanceof NothingToDraw);
  const dir = mkdtempSync(join(tmpdir(), 'mg47-'));
  writeFileSync(join(dir, 'd.json'), JSON.stringify(d));
  assert.equal(cli('--descriptor', join(dir, 'd.json'), '--out', join(dir, 'x.lv2')).status, 3);
});
